import { Router } from 'express';
import crypto from 'node:crypto';
import { requireAuth, optionalAuth } from '../middleware/auth.js';
import { prisma } from '../lib/prisma.js';
import { HttpError } from '../middleware/error.js';

export const serverRouter = Router();

// Channel ids are not auto-generated by Prisma (the model has no @default),
// so we mint a collision-resistant id ourselves. The old
// `Math.random().toString(36).substring(7)` produced 0–6 char ids that could
// be empty or collide, breaking channel creation under load.
function newChannelId() {
  return crypto.randomUUID();
}

// Fetch servers the user is a member of
serverRouter.get('/servers', requireAuth, async (req, res, next) => {
  try {
    const servers = await prisma.server.findMany({
      where: { members: { some: { userId: req.user.id } } },
      include: {
        channels: true,
        members: { include: { user: true } },
      },
    });
    res.json(servers);
  } catch (e) { next(e); }
});

// Create a server
serverRouter.post('/servers', requireAuth, async (req, res, next) => {
  try {
    const { name, description, icon } = req.body;
    if (!name) throw new HttpError(400, 'Server name is required');

    const server = await prisma.server.create({
      data: {
        name,
        description,
        icon,
        ownerId: req.user.id,
        members: {
          create: [{ userId: req.user.id, role: 'FOUNDER' }]
        },
        channels: {
          create: [{ id: newChannelId(), name: 'general', type: 'TEXT' }]
        }
      },
      include: { channels: true, members: { include: { user: true } } }
    });

    res.status(201).json({ server });
  } catch (e) { next(e); }
});

// Create a channel
serverRouter.post('/servers/:id/channels', requireAuth, async (req, res, next) => {
  try {
    const serverId = req.params.id;
    const { name, type } = req.body;
    if (!name) throw new HttpError(400, 'Channel name is required');

    const server = await prisma.server.findUnique({ where: { id: serverId } });
    if (!server) throw new HttpError(404, 'Server not found');

    const member = await prisma.serverMember.findUnique({
      where: { serverId_userId: { serverId, userId: req.user.id } }
    });
    if (!member || (member.role !== 'FOUNDER' && member.role !== 'ADMIN')) {
      throw new HttpError(403, 'Not authorized');
    }

    const channel = await prisma.channel.create({
      data: {
        id: newChannelId(),
        name: name.toLowerCase().replace(/\s+/g, '-'),
        type: type === 'VOICE' ? 'VOICE' : 'TEXT',
        serverId
      }
    });

    res.status(201).json({ channel });
  } catch (e) { next(e); }
});

// Delete a server
serverRouter.delete('/servers/:id', requireAuth, async (req, res, next) => {
  try {
    const serverId = req.params.id;
    const server = await prisma.server.findUnique({ where: { id: serverId } });
    if (!server) throw new HttpError(404, 'Server not found');
    if (server.ownerId !== req.user.id) throw new HttpError(403, 'Only owner can delete server');

    await prisma.server.delete({ where: { id: serverId } });
    res.json({ message: 'Server deleted' });
  } catch (e) { next(e); }
});

// Update a server (name/description/icon/banner/category/public). Founder/Admin.
serverRouter.patch('/servers/:id', requireAuth, async (req, res, next) => {
  try {
    const serverId = req.params.id;
    const member = await prisma.serverMember.findUnique({
      where: { serverId_userId: { serverId, userId: req.user.id } },
    });
    if (!member || !['FOUNDER', 'ADMIN'].includes(member.role)) {
      throw new HttpError(403, 'Not authorized');
    }
    const { name, description, icon, banner, category, isPublic } = req.body || {};
    const data = {};
    if (typeof name === 'string' && name.trim()) data.name = name.trim().slice(0, 100);
    if (typeof description === 'string') data.description = description.slice(0, 500);
    if (typeof icon === 'string') data.icon = icon.slice(0, 1024);
    if (typeof banner === 'string') data.banner = banner.slice(0, 1024);
    if (typeof category === 'string') data.category = category.slice(0, 40);
    if (typeof isPublic === 'boolean') data.isPublic = isPublic;

    const updated = await prisma.server.update({
      where: { id: serverId },
      data,
      include: { channels: true, members: { include: { user: true } } },
    });
    res.json({ server: updated });
  } catch (e) { next(e); }
});

// Server discovery — list public servers, optionally filtered by category and
// a search term, sorted by member count. Auth optional: logged-in users get a
// `joined` flag per server so the JOIN button can switch to "JOINED ✓".
const VALID_CATEGORIES = [
  'GAMING', 'DARK_ARTS', 'TECH', 'MUSIC', 'ANIME',
  'CREATIVE', 'CRYPTO', '18+', 'COMMUNITY',
];

serverRouter.get('/servers/discover', optionalAuth, async (req, res, next) => {
  try {
    const category = String(req.query.category || 'ALL').toUpperCase();
    const search = String(req.query.search || '').trim();
    const limit = Math.min(Number(req.query.limit) || 20, 50);

    const where = { isPublic: true };
    if (category !== 'ALL' && VALID_CATEGORIES.includes(category)) {
      where.category = category;
    }
    if (search) {
      where.OR = [
        { name: { contains: search } },
        { description: { contains: search } },
      ];
    }

    const servers = await prisma.server.findMany({
      where,
      include: {
        channels: { take: 1 },
        _count: { select: { members: true } },
      },
    });

    // Online counts would require presence tracking; approximate as members
    // for now and derive a deterministic pseudo-online figure so the UI has a
    // number to render. (Presence is Phase 5.)
    const myMemberServers = req.user
      ? (
          await prisma.serverMember.findMany({
            where: { userId: req.user.id },
            select: { serverId: true },
          })
        ).map((m) => m.serverId)
      : [];

    const out = servers
      .map((s) => ({
        id: s.id,
        name: s.name,
        description: s.description || '',
        icon: s.icon || null,
        banner: s.banner || null,
        category: s.category || 'COMMUNITY',
        memberCount: s._count.members,
        online: Math.max(1, Math.floor(s._count.members * 0.18)),
        joined: myMemberServers.includes(s.id),
      }))
      .sort((a, b) => b.memberCount - a.memberCount)
      .slice(0, limit);

    res.json({ servers: out });
  } catch (e) { next(e); }
});

// Join a server directly by id (no invite code). Public servers allow this;
// otherwise a member/admin invitation flow is used via /api/invites/:code/join.
serverRouter.post('/servers/:id/join', requireAuth, async (req, res, next) => {
  try {
    const serverId = req.params.id;
    const server = await prisma.server.findUnique({ where: { id: serverId } });
    if (!server) throw new HttpError(404, 'Server not found.');
    if (!server.isPublic) throw new HttpError(403, 'This realm is invite-only.');

    const existing = await prisma.serverMember.findUnique({
      where: { serverId_userId: { serverId, userId: req.user.id } },
    });
    if (existing) {
      const full = await prisma.server.findUnique({
        where: { id: serverId },
        include: { channels: true, members: { include: { user: true } } },
      });
      return res.json({ server: full, alreadyMember: true });
    }

    await prisma.serverMember.create({
      data: { serverId, userId: req.user.id, role: 'MEMBER' },
    });
    const full = await prisma.server.findUnique({
      where: { id: serverId },
      include: { channels: true, members: { include: { user: true } } },
    });
    res.status(201).json({ server: full, alreadyMember: false });
  } catch (e) { next(e); }
});

// Leave a server.
serverRouter.post('/servers/:id/leave', requireAuth, async (req, res, next) => {
  try {
    const serverId = req.params.id;
    const server = await prisma.server.findUnique({ where: { id: serverId } });
    if (!server) throw new HttpError(404, 'Server not found.');
    if (server.ownerId === req.user.id) {
      throw new HttpError(400, 'Owners cannot leave their own realm. Delete it instead.');
    }
    await prisma.serverMember.deleteMany({ where: { serverId, userId: req.user.id } });
    res.json({ left: true });
  } catch (e) { next(e); }
});
